 const subjectTranslationKeys=["relevance", "development", "benefit", "curiosity", "compare", "interrupt", "success", "hello", "partnership", "together", "congratulations", "onbehalf", "human", "fit", "default"];
 function subjectPattern(mode,id,language='en'){
  const original=subjectsFor(mode).find(t=>t.id===id)?.pattern||'';
  if(language==='en')return original;
  if(id==='introduction')return original;
  if(mode==='professional')return professionalSubjectTranslations[language]?.[id]||'';
  if(mode==='brutal'&&id==='project')return original;
  if(mode==='curiosity'&&id==='project')return original; // Both slots are evidence, with no fixed language text.
  const key=mode==='professional'&&id==='curiosity'?'curiosity':id;
  return subjectTranslations[language]?.[subjectTranslationKeys.indexOf(key)]||'';
 }
