   if(mode==='professional'||t.id==='introduction'||t.id==='project')continue;const parts=t.pattern.split(/(\{\{\w+\}\})/),fields=[];
   const regex=new RegExp('^'+parts.map(part=>{if(part.startsWith('{{')){fields.push(part);return '(.+?)';}return part.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');}).join('')+'$');
